mapper.select:
SELECT enterprise_parameter_code, enterprise_code, process_code, parameter_name, value, remark, create_time, update_time, delete_flag FROM ${tableName} WHERE delete_flag = false AND enterprise_code = #{enterpriseCode}
AND process_code = #{processCode}
AND parameter_name = #{parameterName}
ORDER BY id ASC

mapper.update:
UPDATE ${tableName}
SET remark = #{remark}

    , value = #{value}

WHERE delete_flag = false
  AND enterprise_parameter_code = #{enterpriseParameterCode}

mapper.delete:
DELETE
FROM ${tableName}
WHERE enterprise_parameter_code = #{enterpriseParameterCode}
  AND delete_flag = false
